script:
frappe.ui.form.on('TDS Product Specification', {
    setup: function(frm) {
        if (frm.doc.__islocal && !frm.doc.tds_sequence) {
            get_next_sequence(frm);
        }
    },
    
    refresh: function(frm) {
        frm.add_custom_button(__('Generate Version'), function() {
            generate_version(frm);
        }, __('Actions')).addClass('btn-primary');
        
        update_preview(frm);
    },
    
    product_item: function(frm) {
        if (frm.doc.product_item) {
            frappe.db.get_value('Item', frm.doc.product_item, 'item_code')
                .then(r => {
                    frm.set_value('item_code', r.message.item_code);
                    if (frm.doc.__islocal) get_next_sequence(frm);
                    update_preview(frm);
                });
        }
    }
});

// Get next sequence number from TDS Settings
function get_next_sequence(frm) {
    if (!frm.doc.item_code) return;
    
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'TDS Settings',
            filters: { item_code: frm.doc.item_code },
            fields: ['name', 'last_sequence_used']
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                // Existing record found
                const settings = r.message[0];
                const next_seq = (settings.last_sequence_used || 0) + 1;
                frm.set_value('tds_sequence', next_seq);
                update_sequence_in_settings(settings.name, next_seq);
            } else {
                // Create new TDS Settings record
                frappe.call({
                    method: 'frappe.client.insert',
                    args: {
                        doc: {
                            doctype: 'TDS Settings',
                            item_code: frm.doc.item_code,
                            last_sequence_used: 0
                        }
                    },
                    callback: function(r) {
                        frm.set_value('tds_sequence', 1);
                        update_sequence_in_settings(r.message.name, 1);
                    }
                });
            }
        }
    });
}

// Update sequence in TDS Settings
function update_sequence_in_settings(name, sequence) {
    frappe.call({
        method: 'frappe.client.set_value',
        args: {
            doctype: 'TDS Settings',
            name: name,
            fieldname: { last_sequence_used: sequence }
        }
    });
}

// Generate final version number
function generate_version(frm) {
    if (!validate_required_fields(frm)) return;
    
    const date_parts = frm.doc.approval_date.split('-');
    const version = `V1.${frm.doc.item_code}-Date:${date_parts[0].slice(-2)}/${date_parts[1]}/${date_parts[2]}*${String(frm.doc.tds_sequence).padStart(4, '0')}`;
    
    frm.set_value('tds_version', version);
    frappe.show_alert(__('Version generated successfully'));
}

// Validate required fields
function validate_required_fields(frm) {
    let valid = true;
    
    if (!frm.doc.item_code) {
        frappe.msgprint(__('Item Code is required'));
        valid = false;
    }
    if (!frm.doc.approval_date) {
        frappe.msgprint(__('Approval Date is required'));
        valid = false;
    }
    if (!frm.doc.tds_sequence) {
        frappe.msgprint(__('Sequence Number is required'));
        valid = false;
    }
    
    return valid;
}

// Update version preview
function update_preview(frm) {
    if (frm.doc.item_code && frm.doc.approval_date && frm.doc.tds_sequence) {
        const date_parts = frm.doc.approval_date.split('-');
        const preview = `Preview: V1.${frm.doc.item_code}-Date:${date_parts[0].slice(-2)}/${date_parts[1]}/${date_parts[2]}*${String(frm.doc.tds_sequence).padStart(4, '0')}`;
        
        if (!frm.fields_dict.version_preview) {
            frm.add_custom_field('version_preview', {
                fieldtype: 'Section Break',
                label: 'Version Preview',
                description: preview
            });
        } else {
            frm.set_df_property('version_preview', 'description', preview);
        }
    }
}
frappe.ui.form.on('TDS Product Specification', {
    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action === 'Approve' && !frm.doc.approval_date) {
            frappe.call({
                method: 'frappe.utils.nowdate',
                callback: function(r) {
                    frm.set_value('approval_date', r.message);
                }
            });
        }
    }
});

frappe.ui.form.on('TDS Product Specification', {
    item: function(frm) {
        if (!frm.doc.item) {
            frm.set_value('product_code', null);
            return;
        }
        
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                'doctype': 'Item',
                'filters': {'name': frm.doc.item},
                'fieldname': ['product_code', 'item_code']  // Try multiple fields
            },
            callback: function(r) {
                let product_code = r.message.product_code || 
                                  r.message.item_code || 
                                  frm.doc.item.substring(0,4);  // Fallback
                frm.set_value('product_code', product_code);
                
                // If version depends on this, trigger update
                if (frm.doc.custom_version) {
                    frm.trigger('refresh');
                }
            }
        });
    }
});

frappe.ui.form.on('TDS Settings', {
    refresh: function(frm) {
        frm.add_custom_button(__('Generate Version'), function() {
            // Validate required fields exist
            if (!frm.doc.naming_series) {
                frappe.msgprint(__('Naming Series is required'));
                return;
            }
            if (!frm.doc.tds_version_counter) {
                frappe.msgprint(__('Version Counter is required'));
                return;
            }
            if (!frm.doc.item_code) {
                frappe.msgprint(__('Item Code is required'));
                return;
            }
            if (frm.doc.tds_series_counter === undefined || frm.doc.tds_series_counter === null) {
                frappe.msgprint(__('Series Counter is required'));
                return;
            }

            // Extract all digits from naming series (e.g., "1707" from "TDS-1707")
            const allDigits = frm.doc.name.replace(/\D/g, '');
            
            // Validate we have at least 4 digits
            if (allDigits.length < 4) {
                frappe.msgprint(__('Naming Series must contain at least 4 digits', allDigits));
                return;
            }

            // Get last 4 digits
            const last_four = allDigits.slice(-4);

            // Generate current date components
            const today = new Date();
            const yy = today.getFullYear().toString().slice(-2);
            const mm = String(today.getMonth() + 1).padStart(2, '0');
            const dd = String(today.getDate()).padStart(2, '0');

            // Create version string
            const version = `V${frm.doc.tds_version_counter}-${frm.doc.item_code}-Date:${yy}/${mm}/${dd}*${frm.doc.tds_series_counter}${last_four}`;

            // Update the field and show success
            frm.set_value('tds_naming_series', version);
            frappe.show_alert({
                message: __('Version generated successfully'),
                indicator: 'green'
            });
        }).addClass('btn-primary');
    }
});

frappe.ui.form.on('TDS Product Specification', {
    refresh: function(frm) {
        // Add button to fetch TDS version
        frm.add_custom_button(__('Fetch TDS Version'), function() {
            fetchFilteredTdsVersion(frm);
        }).addClass('btn-primary');
    }
});

function fetchFilteredTdsVersion(frm) {
    // Validate we have an item code to filter by
    if (!frm.doc.item_code) {
        frappe.msgprint(__('Please select an Item Code first'));
        return;
    }

    // Validate we have a TDS Settings link
    if (!frm.doc.tds_settings) {
        frappe.msgprint(__('Please select a TDS Settings document first'));
        return;
    }

    frappe.call({
        method: 'frappe.client.get_value',
        args: {
            doctype: 'TDS Settings',
            filters: {
                name: frm.doc.tds_settings,
                item_code: frm.doc.item_code  // This ensures we only match the correct product
            },
            fieldname: ['tds_naming_series']
        },
        callback: function(r) {
            if (r.message && r.message.tds_naming_series) {
                frm.set_value('version', r.message.tds_naming_series);
                frappe.show_alert(__('TDS Version fetched successfully'));
            } else {
                frappe.msgprint(__('No matching TDS Version found for this product'));
            }
        }
    });
}

frappe.ui.form.on('COA AMB', {
    onload: function(frm) {
        // Only set the value if the document is new and the field is empty
        if (frm.is_new() && frm.doc.naming_series) {
            frm.set_value('naming_series', '');
        }
    }
});

frappe.provide('erpnext.sales');

erpnext.sales.SalesOrderPDFProcessor = class {
    constructor(frm) {
        this.frm = frm;
        this.setup_events();
    }

    setup_events() {
        // Add PDF processing button to form
        this.frm.add_custom_button(__('Process PDF'), () => {
            this.process_pdf();
        }, __('Tools'));
    }

    process_pdf() {
        // Show dialog to paste PDF content
        const d = new frappe.ui.Dialog({
            title: __('Process PDF Content'),
            fields: [
                {
                    fieldname: 'pdf_content',
                    fieldtype: 'Text',
                    label: __('PDF Text Content'),
                    reqd: 1,
                    rows: 10
                }
            ],
            primary_action: ({ pdf_content }) => {
                d.hide();
                this.submit_pdf_content(pdf_content);
            },
            primary_action_label: __('Process')
        });

        d.show();
    }

    submit_pdf_content(pdf_content) {
        frappe.call({
            method: 'your_app.sales_order_pdf_processor.process_sales_order_pdf',
            args: {
                pdf_content: pdf_content,
                sales_order_name: this.frm.doc.name
            },
            freeze: true,
            freeze_message: __('Processing PDF content...'),
            callback: (r) => {
                if (r.message.status === 'success') {
                    frappe.show_alert({
                        message: __('PDF processed successfully'),
                        indicator: 'green'
                    });
                    this.frm.reload_doc();
                } else {
                    frappe.msgprint({
                        title: __('Processing Failed'),
                        message: r.message.message,
                        indicator: 'red'
                    });
                }
            }
        });
    }
};

// Add to Sales Order form
frappe.ui.form.on('Sales Order', {
    refresh: function(frm) {
        if (!frm.sales_order_pdf_processor) {
            frm.sales_order_pdf_processor = new erpnext.sales.SalesOrderPDFProcessor(frm);
        }
    }
});

frappe.ui.form.on('Quotation Item Escalated', {
    item_code: function(frm, cdt, cdn) {
        // Fetch item details when item code changes
        var row = frappe.get_doc(cdt, cdn);
        if (row.item_code) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Item",
                    name: row.item_code
                },
                callback: function(r) {
                    if (r.message) {
                        frappe.model.set_value(cdt, cdn, 'item_name', r.message.item_name);
                        frappe.model.set_value(cdt, cdn, 'description', r.message.description);
                        frappe.model.set_value(cdt, cdn, 'item_group', r.message.item_group);
                        frappe.model.set_value(cdt, cdn, 'brand', r.message.brand);
                        frappe.model.set_value(cdt, cdn, 'stock_uom', r.message.stock_uom);
                        frappe.model.set_value(cdt, cdn, 'weight_per_unit', r.message.weight_per_unit);
                        frappe.model.set_value(cdt, cdn, 'weight_uom', r.message.weight_uom);
                        
                        // Set UOM conversion factor to 1 by default
                        frappe.model.set_value(cdt, cdn, 'uom', r.message.stock_uom);
                        frappe.model.set_value(cdt, cdn, 'conversion_factor', 1);
                    }
                }
            });
        }
    },

    qty: function(frm, cdt, cdn) {
        // Recalculate when quantity changes
        recalculate_row(frm, cdt, cdn);
        update_stock_details(frm, cdt, cdn);
    },

    conversion_factor: function(frm, cdt, cdn) {
        // Recalculate stock quantity
        var row = frappe.get_doc(cdt, cdn);
        if (row.qty && row.conversion_factor) {
            frappe.model.set_value(cdt, cdn, 'stock_qty', 
                flt(row.qty) * flt(row.conversion_factor));
        }
    },

    price_list_rate: function(frm, cdt, cdn) {
        recalculate_row(frm, cdt, cdn);
    },

    discount_percentage: function(frm, cdt, cdn) {
        calculate_discount(frm, cdt, cdn);
    },

    discount_amount: function(frm, cdt, cdn) {
        calculate_discount_from_amount(frm, cdt, cdn);
    },

    ex_works_price: function(frm, cdt, cdn) {
        calculate_delivered_price(frm, cdt, cdn);
    },

    freight_cost: function(frm, cdt, cdn) {
        calculate_delivered_price(frm, cdt, cdn);
    },

    freight_location: function(frm, cdt, cdn) {
        // Fetch freight cost when freight location changes
        fetch_freight_cost_and_calculate(frm, cdt, cdn);
    }
});

// Function to recalculate entire row
function recalculate_row(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    
    // Calculate freight cost based on quantity
    var freight_cost = calculate_freight_cost(row.qty);
    frappe.model.set_value(cdt, cdn, 'freight_cost', freight_cost);
    
    // Apply quantity-based escalation
    var escalated_price = apply_quantity_escalation(row.price_list_rate, row.qty);
    frappe.model.set_value(cdt, cdn, 'escalated_rate', escalated_price);
    
    // Calculate final rate
    var final_rate = flt(escalated_price) + flt(freight_cost);
    frappe.model.set_value(cdt, cdn, 'rate', final_rate);
    
    // Calculate amount
    if (row.qty && final_rate) {
        var amount = flt(row.qty) * final_rate;
        frappe.model.set_value(cdt, cdn, 'amount', amount);
        
        // Recalculate discount if percentage is set
        if (row.discount_percentage) {
            calculate_discount(frm, cdt, cdn);
        }
    }

    // Calculate delivered price
    calculate_delivered_price(frm, cdt, cdn);
}

// Calculate delivered price (ex_works_price + freight_cost)
function calculate_delivered_price(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    var ex_works_price = flt(row.ex_works_price) || 0;
    var freight_cost = flt(row.freight_cost) || 0;
    
    var delivered_price = ex_works_price + freight_cost;
    frappe.model.set_value(cdt, cdn, 'delivered_price', delivered_price);
}

// Fetch freight cost from freight location and calculate delivered price
function fetch_freight_cost_and_calculate(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    
    if (row.freight_location) {
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Freight Location", // Replace with your actual doctype name
                filters: { name: row.freight_location },
                fieldname: ["freight_cost"] // Replace with actual field name for freight cost
            },
            callback: function(r) {
                if (r.message && r.message.freight_cost) {
                    // Set the freight cost from the freight location
                    frappe.model.set_value(cdt, cdn, 'freight_cost', r.message.freight_cost);
                    
                    // Recalculate delivered price
                    calculate_delivered_price(frm, cdt, cdn);
                    
                    // Also trigger row recalculation
                    recalculate_row(frm, cdt, cdn);
                }
            }
        });
    }
}

// Calculate freight cost based on quantity
function calculate_freight_cost(quantity) {
    quantity = flt(quantity);
    if (quantity <= 1) return 58.30;
    if (quantity <= 5) return 19.87;
    if (quantity <= 10) return 16.06;
    if (quantity <= 20) return 14.17;
    return 13.91;
}

// Apply quantity-based price escalation
function apply_quantity_escalation(base_price, quantity) {
    base_price = flt(base_price);
    quantity = flt(quantity);
    
    if (quantity >= 100) return base_price * 0.9;      // 10% discount
    if (quantity >= 50) return base_price * 0.95;      // 5% discount
    return base_price;
}

// Calculate discount from percentage
function calculate_discount(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    if (row.discount_percentage && row.amount) {
        var discount_amount = flt(row.amount) * flt(row.discount_percentage) / 100;
        frappe.model.set_value(cdt, cdn, 'discount_amount', discount_amount);
        
        var net_amount = flt(row.amount) - discount_amount;
        frappe.model.set_value(cdt, cdn, 'net_amount', net_amount);
        
        if (row.qty) {
            var net_rate = net_amount / flt(row.qty);
            frappe.model.set_value(cdt, cdn, 'net_rate', net_rate);
        }
    }
}

// Calculate discount percentage from amount
function calculate_discount_from_amount(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    if (row.discount_amount && row.amount) {
        var discount_percentage = (flt(row.discount_amount) / flt(row.amount)) * 100;
        frappe.model.set_value(cdt, cdn, 'discount_percentage', discount_percentage);
        
        var net_amount = flt(row.amount) - flt(row.discount_amount);
        frappe.model.set_value(cdt, cdn, 'net_amount', net_amount);
        
        if (row.qty) {
            var net_rate = net_amount / flt(row.qty);
            frappe.model.set_value(cdt, cdn, 'net_rate', net_rate);
        }
    }
}

// Update stock details
function update_stock_details(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    if (row.item_code && row.warehouse) {
        frappe.call({
            method: "erpnext.stock.get_item_details.get_available_quantity",
            args: {
                item_code: row.item_code,
                warehouse: row.warehouse
            },
            callback: function(r) {
                if (r.message) {
                    frappe.model.set_value(cdt, cdn, 'actual_qty', r.message);
                }
            }
        });
    }
}

frappe.ui.form.on('Quotation Item Escalated', {
    quantity_range: function(frm, cdt, cdn) {
        set_quantity_limits(frm, cdt, cdn);
        calculate_prices(frm, cdt, cdn);
    },
    
    ex_works_price: function(frm, cdt, cdn) {
        calculate_prices(frm, cdt, cdn);
    },
    
    freight_cost: function(frm, cdt, cdn) {
        calculate_prices(frm, cdt, cdn);
    },
    
    freight_type: function(frm, cdt, cdn) {
        calculate_freight_based_on_type(frm, cdt, cdn);
    }
});

function set_quantity_limits(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    
    switch(row.quantity_range) {
        case '1-5 kg':
            row.min_quantity = 1;
            row.max_quantity = 5;
            break;
        case '6-10 kg':
            row.min_quantity = 6;
            row.max_quantity = 10;
            break;
        case '11-25 kg':
            row.min_quantity = 11;
            row.max_quantity = 25;
            break;
        case '26-200 kg':
            row.min_quantity = 26;
            row.max_quantity = 200;
            break;
        default:
            row.min_quantity = 0;
            row.max_quantity = 0;
    }
    
    frappe.model.set_value(cdt, cdn, 'min_quantity', row.min_quantity);
    frappe.model.set_value(cdt, cdn, 'max_quantity', row.max_quantity);
}

function calculate_freight_based_on_type(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    var freight_cost = 0;
    
    // Set freight cost based on quantity range and freight type
    if (row.quantity_range && row.freight_type) {
        switch(row.quantity_range) {
            case '1-5 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 58.30 : 
                              (row.freight_type === 'Sea Freight') ? 45.00 :
                              (row.freight_type === 'Ground') ? 35.00 : 60.00;
                break;
            case '6-10 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 19.87 : 
                              (row.freight_type === 'Sea Freight') ? 15.00 :
                              (row.freight_type === 'Ground') ? 12.00 : 22.00;
                break;
            case '11-25 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 16.06 : 
                              (row.freight_type === 'Sea Freight') ? 12.00 :
                              (row.freight_type === 'Ground') ? 9.00 : 18.00;
                break;
            case '26-200 kg':
                freight_cost = (row.freight_type === 'Air Freight') ? 13.91 : 
                              (row.freight_type === 'Sea Freight') ? 10.00 :
                              (row.freight_type === 'Ground') ? 7.00 : 15.00;
                break;
        }
        
        frappe.model.set_value(cdt, cdn, 'freight_cost', freight_cost);
        calculate_prices(frm, cdt, cdn);
    }
}

function calculate_prices(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    
    if (row.ex_works_price && row.freight_cost && row.min_quantity && row.max_quantity) {
        // Calculate delivered price per kg
        var delivered_price = flt(row.ex_works_price) + flt(row.freight_cost);
        frappe.model.set_value(cdt, cdn, 'delivered_price', delivered_price);
        
        // Calculate price per kg
        frappe.model.set_value(cdt, cdn, 'price_per_kg', delivered_price);
        
        // Calculate total price range (min and max)
        var min_total = delivered_price * row.min_quantity;
        var max_total = delivered_price * row.max_quantity;
        
        // Display as range or single value
        if (row.min_quantity === row.max_quantity) {
            frappe.model.set_value(cdt, cdn, 'total_price', min_total);
        } else {
            frappe.model.set_value(cdt, cdn, 'total_price', max_total);
            // You could also display as range: min_total + " - " + max_total
        }
    }
}

frappe.ui.form.on('Sales Order', {
    custom_item_name: function(frm) {
        if (frm.doc.custom_item_name) {
            fetch_tds_options_for_item(frm);
        }
    },
    
    custom_tds_amb: function(frm) {
        if (frm.doc.custom_tds_amb) {
            fetch_tds_details(frm);
        }
    },
    
    refresh: function(frm) {
        frm.add_custom_button(__('Refresh TDS Details'), function() {
            if (frm.doc.custom_tds_amb) {
                fetch_tds_details(frm);
            } else if (frm.doc.custom_item_name) {
                fetch_tds_options_for_item(frm);
            } else {
                frappe.msgprint(__('Please select TDS AMB or Item Name first'));
            }
        }, __('Custom'));
        
        // Add button to add item to table
        frm.add_custom_button(__('Add Item to Table'), function() {
            add_item_to_table(frm);
        }, __('Custom'));
    }
});

// Main function: Fetch all TDS options for the selected item
function fetch_tds_options_for_item(frm) {
    if (!frm.doc.custom_item_name) return;
    
    console.log("=== FETCHING TDS OPTIONS FOR ITEM ===");
    
    // First get item details to have the item name
    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "Item",
