/**
 * Fetch customer country from shipping or billing address
 * Priority: 1. Shipping Address, 2. Customer Address (Billing)
 */
function fetch_customer_country(frm) {
    // Clear existing country if no customer
    if (!frm.doc.customer) {
        frm.set_value('custom_customer_shipment_country', '');
        return;
    }

    // Determine which address to fetch from (priority: shipping > billing)
    let address_name = frm.doc.shipping_address_name || frm.doc.customer_address;

    if (!address_name) {
        console.log('No address selected yet');
        return;
    }

    // Fetch address details from ERPNext
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Address',
            name: address_name
        },
        callback: function(r) {
            if (r.message && r.message.country) {
                // Set the country in the custom field
                frm.set_value('custom_customer_shipment_country', r.message.country);

                console.log('✅ Customer country fetched:', r.message.country);

                // Show notification to user
                frappe.show_alert({
                    message: __('Customer country set to: {0}', [r.message.country]),
                    indicator: 'green'
                }, 3);
            } else {
                frappe.show_alert({
                    message: __('Country not found in address'),
                    indicator: 'orange'
                }, 3);
            }
        },
        error: function(r) {
            console.error('Error fetching address:', r);
            frappe.show_alert({
                message: __('Error fetching address country'),
                indicator: 'red'
            }, 3);
        }
    });
}

/**
 * Set filter on custom_freigh_shipment_rule based on customer country
 * Only shows shipping rules where custom_applicable_country matches
 */
function set_freight_shipment_rule_filter(frm) {
    let country = frm.doc.custom_customer_shipment_country;

    if (country) {
        // Filter shipping rules by applicable country
        frm.set_query('custom_freigh_shipment_rule', function() {
            return {
                filters: {
                    'custom_applicable_country': country
                }
            };
        });

        console.log('🔍 Freight shipment rule filtered by country:', country);
    } else {
        // No filter if country not set - show all shipping rules
        frm.set_query('custom_freigh_shipment_rule', function() {
            return {};
        });

        console.log('🔍 No country filter applied - showing all shipping rules');
    }
}

/**
 * Apply the selected freight shipment rule to the standard shipping_rule field
 * This follows ERPNext best practices (Option B)
 */
function apply_freight_shipment_rule(frm) {
    let selected_rule = frm.doc.custom_freigh_shipment_rule;

    if (!selected_rule) {
        // Clear shipping rule if custom rule is cleared
        frm.set_value('shipping_rule', '');
        return;
    }

    // Apply the selected rule to the standard ERPNext shipping_rule field
    frm.set_value('shipping_rule', selected_rule);

    console.log('✅ Freight shipment rule applied:', selected_rule);

    // Show notification
    frappe.show_alert({
        message: __('Shipping rule applied: {0}', [selected_rule]),
        indicator: 'green'
    }, 3);

    // Trigger shipping rule calculation
    // ERPNext's standard shipping rule will automatically:
    // 1. Calculate the shipping cost
    // 2. Add it to the "Taxes and Charges" section
    // 3. Update the grand total
    frm.trigger('shipping_rule');
}

