        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                // Found TDS options
                const tds_list = r.message;
                console.log('   📋 Found', tds_list.length, 'TDS options:');
                tds_list.forEach(function(t, idx) {
                    console.log('      [' + idx + '] ' + t.name);
                });
                
                // Set first one as default (usually BASE)
                const default_tds = tds_list[0];
                
                // Set on main TDS field (v8.28 functionality)
                frm.set_value('custom_tds_amb', default_tds.name);
