// ============================================================================
// FUNCTION 2: POPULATE ESCALATED TABLE WITH 5 WEIGHT RANGES (v8.26)
// ============================================================================

function populate_escalated_table_all_ranges(frm) {
    console.log('\n📋 Populate Escalated Table (5 ranges per item) - v8.26');
    
    if (!frm.doc.shipping_rule) {
        console.log('   ⚠️ No shipping rule set');
        return;
    }
    
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Shipping Rule',
            name: frm.doc.shipping_rule
        },
        callback: function(r) {
            if (!r.message) {
                console.error('   ❌ Failed to fetch shipping rule');
                tax_update_in_progress = false;
                return;
            }
            
            const weight_ranges = r.message.conditions || [];
            console.log('   📊 Shipping rule has ' + weight_ranges.length + ' weight ranges');
            
            frm.clear_table('custom_quotation_child_table');
            
            const valid_items = get_valid_items(frm);
            console.log('   🔍 Found ' + (frm.doc.items ? frm.doc.items.length : 0) + ' item(s) in Quotation Item table');
            console.log('   ✅ Valid items: ' + valid_items.length);
            
            if (valid_items.length === 0) {
                console.log('   ⚠️ No valid items yet - waiting for item selection');
                frappe.show_alert({
                    message: __('Please select an item in the Items table first'),
                    indicator: 'orange'
                }, 4);
                return;
            }
            
            let rows_created = 0;
            
            valid_items.forEach(function(item, item_idx) {
                console.log('\n   📦 Item ' + (item_idx + 1) + ': ' + item.item_code);
                
                CUSTOM_QUANTITY_RANGES.forEach(function(range, range_idx) {
                    const freight_rate = find_freight_rate(weight_ranges, range.qty);
                    
                    const ex_works_price = parseFloat(item.rate) || 0;
                    const freight_cost = freight_rate * range.qty;
                    const rate_per_kg = ex_works_price + freight_rate;
                    const delivered_price = (ex_works_price * range.qty) + freight_cost;
                    
                    const escalated_row = frm.add_child('custom_quotation_child_table');
                    escalated_row.item_code = item.item_code;
                    escalated_row.item_name = item.item_name || item.item_code;
                    escalated_row.uom = item.uom || 'Kg';
                    escalated_row.quantity_range = range.display;
                    escalated_row.qty = range.qty;
                    escalated_row.ex_works_price = ex_works_price;
                    escalated_row.freight_cost = freight_rate;  // v8.27: Show RATE per kg, not total
                    escalated_row.rate = rate_per_kg;
                    escalated_row.escalated_rate = rate_per_kg;
                    escalated_row.delivered_price = delivered_price;
                    escalated_row.amount = rate_per_kg * range.qty;
                    
                    rows_created++;
                });
                
                console.log('      → Created 5 rows for ' + item.item_code);
            });
            
            frm.refresh_field('custom_quotation_child_table');
            
            console.log('\n   ✅ Total rows created: ' + rows_created + ' (' + valid_items.length + ' items × 5 ranges)');
            
            frappe.show_alert({
                message: __('✅ Created {0} escalated rows ({1} items × 5 ranges)', [rows_created, valid_items.length]),
                indicator: 'green'
            }, 4);
        }
    });
}

// ============================================================================
// FUNCTION 3: UPDATE SALES TAXES - RATE × WEIGHT CALCULATION
// ============================================================================

function update_sales_taxes_for_quantity(frm, quantity) {
    // Check execution lock
    if (tax_update_in_progress) {
        console.log('\n⏱️ [EXECUTION LOCK] Freight update already in progress, skipping duplicate call');
        return;
    }
    
    // Set lock
    tax_update_in_progress = true;
    console.log('\n💰 ========== UPDATE FREIGHT AS ITEM ==========');
    console.log('   🔒 Execution lock ACQUIRED');
    console.log('   📥 Quantity:', quantity);
    console.log('   📥 Shipping Rule:', frm.doc.shipping_rule);
    
    if (!frm.doc.shipping_rule) {
        console.log('   ❌ No shipping rule set');
        tax_update_in_progress = false;
        return;
    }
    
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Shipping Rule',
            name: frm.doc.shipping_rule
        },
        callback: function(r) {
            if (!r.message) {
                console.error('   ❌ Failed to fetch shipping rule');
                tax_update_in_progress = false;
                return;
            }
            
            const rule = r.message;
            const weight_ranges = rule.conditions || [];
            
            console.log('\n   📋 SHIPPING RULE CONDITIONS:');
            weight_ranges.forEach(function(range, idx) {
                console.log('      Range ' + (idx + 1) + ': ' + range.from_value + ' - ' + range.to_value + ' kg → $' + range.shipping_amount + '/kg');
            });
            
            // Find the freight rate for this quantity
            console.log('\n   🔍 Finding freight rate for quantity:', quantity);
            const freight_rate = find_freight_rate(weight_ranges, quantity);
            console.log('   ✅ Freight rate found: $', freight_rate, '/kg');
            
            // RATE × WEIGHT CALCULATION
            const freight_amount = freight_rate * quantity;
            console.log('\n   🧮 RATE × WEIGHT CALCULATION:');
            console.log('      freight_rate =', freight_rate, '/kg');
            console.log('      quantity =', quantity, 'kg');
            console.log('      freight_amount = freight_rate × quantity');
            console.log('      freight_amount =', freight_rate, '×', quantity, '=', freight_amount);
            
            // Find the matching range for description
            let range_desc = quantity + ' kg';
            for (let i = 0; i < weight_ranges.length; i++) {
                const range = weight_ranges[i];
                const from_val = parseFloat(range.from_value || 0);
                const to_val = parseFloat(range.to_value || 999999);
                
                if (quantity > from_val && quantity <= to_val) {
                    range_desc = from_val + ' - ' + to_val + ' kg';
                    break;
                }
            }
            
            // Add freight as an ITEM
            console.log('\n   ➕ ADDING FREIGHT AS ITEM ROW:');
            console.log('      Item Code: Freight Cost');
            console.log('      Quantity: 1');
            console.log('      Rate: $' + freight_amount);
            
            // Remove existing freight items
            const items = frm.doc.items || [];
            const freight_items = items.filter(function(item) { return item.item_code === 'Freight Cost'; });
            
            console.log('      🗑️ Removing', freight_items.length, 'existing freight item(s)');
            
            freight_items.forEach(function(freight_item) {
                frappe.model.clear_doc(freight_item.doctype, freight_item.name);
            });
            
            // Clear the freight items from the array
            frm.doc.items = items.filter(function(item) { return item.item_code !== 'Freight Cost'; });
            frm.refresh_field('items');
            
            // Add new freight item at the end
            const freight_row = frm.add_child('items');
            const item_cdt = freight_row.doctype;
            const item_cdn = freight_row.name;
            
            console.log('      ✅ Adding new freight item row');
            
            // Set all fields using frappe.model.set_value
            frappe.model.set_value(item_cdt, item_cdn, 'item_code', 'Freight Cost');
            frappe.model.set_value(item_cdt, item_cdn, 'item_name', 'Freight Cost');
            frappe.model.set_value(item_cdt, item_cdn, 'description', 
                frm.doc.shipping_rule + ' - ' + range_desc + ' (' + quantity + ' kg × $' + freight_rate + '/kg = $' + freight_amount + ')');
            frappe.model.set_value(item_cdt, item_cdn, 'qty', 1);
            frappe.model.set_value(item_cdt, item_cdn, 'uom', 'Kg');
            frappe.model.set_value(item_cdt, item_cdn, 'rate', freight_amount);
            
            frm.refresh_field('items');
            
            console.log('\n   ✅ Freight added as item row with RATE × WEIGHT calculation');
            console.log('==========================================\n');
            
            frappe.show_alert({
                message: __('✅ Freight: {0} kg × ${1}/kg = ${2} {3}', 
                    [quantity, freight_rate.toFixed(2), freight_amount.toFixed(2), frm.doc.currency]),
                indicator: 'green'
            }, 5);
            
            // Release execution lock after a delay
            setTimeout(function() {
                tax_update_in_progress = false;
                console.log('   🔓 Execution lock RELEASED');
            }, 300);
        }
    });
}

// ============================================================================
// HELPER: FIND FREIGHT RATE FOR A GIVEN QUANTITY
// ============================================================================

function find_freight_rate(weight_ranges, qty) {
    for (let i = 0; i < weight_ranges.length; i++) {
        const range = weight_ranges[i];
        const from_val = parseFloat(range.from_value || 0);
        const to_val = parseFloat(range.to_value || 999999);
        const shipping_amt = parseFloat(range.shipping_amount || 0);
        
        if (qty > from_val && qty <= to_val) {
            return shipping_amt;
        }
    }
    return 0;
}

