/**
 * Set up the shipping rule filter based on country
 * This is the core filtering logic using frm.set_query
 */
function setup_shipping_rule_filter(frm) {
    console.log('🔍 Applying shipping rule filter...');

    // Filter for standard shipping_rule field (Link type)
    frm.set_query('shipping_rule', function() {
        const country = frm.doc.custom_customer_shipment_country;

        if (country) {
            console.log(`✅ Filtering shipping_rule by country: ${country}`);
            return {
                filters: {
                    'custom_applicable_country': country
                }
            };
        } else {
            console.log('⚠️ No country detected yet - showing all shipping rules');
            return {};
        }
    });

    // Filter for custom freight shipment rule field (Link type)
    frm.set_query('custom_freigh_shipment_rule', function() {
        const country = frm.doc.custom_customer_shipment_country;

        if (country) {
            console.log(`✅ Filtering custom_freigh_shipment_rule by country: ${country}`);
            return {
                filters: {
                    'custom_applicable_country': country
                }
            };
        } else {
            console.log('⚠️ No country detected yet - showing all freight shipment rules');
            return {};
        }
    });

    console.log('✅ Shipping rule filters applied to Link fields');
    console.log('ℹ️  Note: custom_shipping_rule_amb_ (Autocomplete) cannot be filtered');
}

/**
 * Fetch country from the selected address
 */
function fetch_country_from_address(frm, address_name) {
    if (!address_name) {
        console.log('⚠️ No address name provided');
        return;
    }

    console.log(`📡 Fetching country for address: ${address_name}`);

    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Address',
            name: address_name
        },
        callback: function(r) {
            if (r.message && r.message.country) {
                const country = r.message.country;
                console.log(`✅ Country detected: ${country}`);

                // Save country to custom field
                frm.set_value('custom_customer_shipment_country', country);

                // Show user-friendly message
                frappe.show_alert({
                    message: `Country detected: ${country}`,
                    indicator: 'blue'
                }, 3);

                // Refresh shipping rule field to apply new filter
                frm.refresh_field('shipping_rule');
                frm.refresh_field('custom_freigh_shipment_rule');

            } else {
                console.log('⚠️ No country found in address');
                frappe.show_alert({
                    message: 'Address has no country set',
                    indicator: 'orange'
                }, 3);
            }
        },
        error: function(err) {
            console.error('❌ Error fetching address:', err);
        }
    });
}

