/**
 * Frappe Client Script for Quotation - Shipping Rule Filter
 * 
 * Purpose: Filter Shipping Rules based on Customer's Country and Incoterm
 * 
 * Flow:
 * 1. When customer is selected → fetch country from address
 * 2. Write country to custom_customer_shipment_country field
 * 3. Filter shipment_rule and custom_freigh_shipment_rule based on:
 *    - Country (from Shipping Rule's countries child table)
 *    - Incoterm (from Shipping Rule's custom_incoterm field)
 * 
 * Author: MiniMax Agent
 * Date: 2025-10-19
 * Version: 6.0 - Simplified and Optimized
 */

frappe.ui.form.on('Quotation', {

    // When customer is selected, fetch and set their country
    customer_name: function(frm) {
        if (frm.doc.customer_name) {
            // Priority 1: Get country from Shipping Address
            let address_name = frm.doc.shipping_address_name;

            // Priority 2: Fallback to Billing Address if no shipping address
            if (!address_name) {
                address_name = frm.doc.customer_address;
            }

            if (address_name) {
                // Fetch the Address document to get country
                frappe.call({
                    method: 'frappe.client.get',
                    args: {
                        doctype: 'Address',
                        name: address_name
                    },
                    callback: function(r) {
                        if (r.message && r.message.country) {
                            // Set the country in the custom field
                            frm.set_value('custom_customer_shipment_country', r.message.country);
                        } else {
                            console.warn('No country found in address:', address_name);
                        }
                    }
                });
            } else {
                console.warn('No shipping or billing address found for customer');
            }
        }
    },

    // Setup function runs when form is loaded
    setup: function(frm) {

        // Function to apply filter to shipping rule fields
        const apply_shipping_rule_filter = function(field_name) {
            frm.set_query(field_name, function() {
                let country = frm.doc.custom_customer_shipment_country;
                let incoterm = frm.doc.incoterm;

                // Both country and incoterm are required for filtering
                if (!country || !incoterm) {
                    // Return a filter that shows nothing if requirements not met
                    return {
                        filters: {
                            'name': ['like', '%PLEASE_SELECT_CUSTOMER_AND_INCOTERM_FIRST%']
                        }
                    };
                }

                // Apply the filter
                return {
                    filters: [
                        ['Shipping Rule', 'custom_incoterm', '=', incoterm],
                        ['Shipping Rule Country', 'country', '=', country]
                    ]
                };
            });
        };

        // Apply filter to both shipping rule fields
        apply_shipping_rule_filter('shipment_rule');
        apply_shipping_rule_filter('custom_freigh_shipment_rule');
    },

    // Refresh the filter when incoterm changes
    incoterm: function(frm) {
        frm.refresh_field('shipment_rule');
        frm.refresh_field('custom_freigh_shipment_rule');
    },

    // Refresh the filter when country changes
    custom_customer_shipment_country: function(frm) {
        frm.refresh_field('shipment_rule');
        frm.refresh_field('custom_freigh_shipment_rule');
    }
});

