function download_bom_items_with_amounts(frm) {
    // Prepare CSV data
    let data = [[
        'Item Code', 'Item Name', 'Item Group', 'Finished Goods Item',
        'Qty', 'Rate (MXN)', 'UOM', 'Amount', 'Stock Qty', 'Conversion Factor',
        'Stock UOM', 'Base Rate', 'Base Amount', 'Parent Row No', 'FG Reference ID'
    ]];

    frm.doc.items.forEach(function(item) {
        let rate = parseFloat(item.rate) || 0;
        let qty = parseFloat(item.qty) || 0;
        let amount = rate * qty;

        data.push([
            item.item_code || '',
            item.item_name || '',
            item.item_group || '',
            item.fg_item || '',
            qty,
            rate,
            item.uom || '',
            amount.toFixed(2),
            item.stock_qty || qty,
            item.conversion_factor || 1,
            item.stock_uom || item.uom || '',
            rate,
            amount.toFixed(2),
            item.parent_row_no || '',
            item.fg_reference_id || ''
        ]);
    });

    // Convert to CSV
    let csv = data.map(row => row.map(cell => {
        // Escape cells with commas
        if (typeof cell === 'string' && (cell.includes(',') || cell.includes('"'))) {
            return '"' + cell.replace(/"/g, '""') + '"';
        }
        return cell;
    }).join(',')).join('\n');

    // Download file
    let filename = 'BOM_Items_' + frm.doc.name + '.csv';
    let blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    let link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    link.click();

    frappe.show_alert({
        message: __('Downloaded {0} items with calculated amounts', [frm.doc.items.length]),
        indicator: 'green'
    });
}

