            var d = new frappe.ui.Dialog({
                title: __('Upload Customer PO PDF'),
                fields: [
                    {
                        fieldname: 'file',
                        fieldtype: 'Attach',
                        label: __('Customer PO File (PDF)'),
                        reqd: 1
                    }
                ],
                primary_action_label: __('Save'),
                primary_action: function(values) {
                    // Simply set the customer_po_file field and save
                    frm.set_value('customer_po_file', values.file);
                    frm.dirty();
                    frm.save().then(function() {
                        frappe.show_alert({
                            message: __('Customer PO linked successfully'),
